      "В пост уходит одно фото, и набор листается по кругу без повторов: обложкой идёт то фото, которое дольше всех не выходило, поэтому одинаковые картинки подряд не повторяются.": "В пост уходит одно фото, и набор листается по кругу без повторов: обложкой идёт то фото, которое дольше всех не выходило, поэтому одинаковые картинки подряд не повторяются.",
      "Файлов можно выбрать сразу много — сохранятся все.": "Файлов можно выбрать сразу много — сохранятся все.",
      "Свои картинки для вечернего выпуска: тот же круг без повторов.": "Свои картинки для вечернего выпуска: тот же круг без повторов.",
      "Можно выбрать сразу много файлов.": "Можно выбрать сразу много файлов.",
      "jpg, png, webp — до 12 МБ каждое, можно выбрать пачку": "jpg, png, webp — до 12 МБ каждое, можно выбрать пачку",
      "Загружаю…": "Загружаю…",
      "Сохранено:": "Сохранено:",
      "Ничего не сохранилось:": "Ничего не сохранилось:",
      "ошибок:": "ошибок:",
      "сверх пачки:": "сверх пачки:",
      "В постах картинки из комплекта. Загрузите свои — набор заменится.": "В постах картинки из комплекта. Загрузите свои — набор заменится.",
      "🕘 Сводка на сайт": "🕘 Сводка на сайт",
      "пробный доступ гостей к слоям": "пробный доступ гостей к слоям",
      "День": "День",
