      "Исчезнут переходы и уникальные посетители, график за две недели, страны, источники переходов, время на сайте и список «кто онлайн». Пользователи, подписки и рассылки останутся. Вернуть статистику нельзя.": "Page views and unique visitors, the two-week chart, countries, traffic sources, time on site and the “who is online” list will be gone. Users, subscriptions and broadcasts stay. Statistics cannot be restored.",
