      "Стираю…": "Clearing…",
      "Пока пусто: переходов за это окно нет.": "Nothing yet: no page views in this window.",
      "Исчезнут переходы и уникальные посетители, график за две недели, страны, источники переходов, время на сайте и список «кто онлайн».": "Page views and unique visitors, the two-week chart, countries, traffic sources, time on site and the “who is online” list will be gone.",
      "Пользователи, подписки и рассылки останутся.": "Users, subscriptions and broadcasts stay.",
      "Вернуть статистику нельзя.": "Statistics cannot be restored.",
      "Отмена": "Cancel",
      "В пост уходит одно фото, и набор листается по кругу без повторов: обложкой идёт то фото, которое дольше всех не выходило, поэтому одинаковые картинки подряд не повторяются.": "A post gets one photo, and the set rotates in a loop with no repeats: the photo waiting the longest becomes the cover, so identical pictures never follow one another.",
      "Файлов можно выбрать сразу много — сохранятся все.": "You can pick many files at once — all of them are saved.",
      "Свои картинки для вечернего выпуска: тот же круг без повторов.": "Your own pictures for the evening issue: the same loop with no repeats.",
      "Можно выбрать сразу много файлов.": "You can pick many files at once.",
      "jpg, png, webp — до 12 МБ каждое, можно выбрать пачку": "jpg, png, webp — up to 12 MB each, you can select a batch",
      "В пост уходит одно фото, и набор листается по кругу без повторов: обложкой идёт то фото, которое дольше всех не выходило, поэтому одинаковые картинки подряд не повторяются. Файлов можно выбрать сразу много — сохранятся все. Альбома нет: он валил все загруженные фото в один пост. Пусто — берутся картинки из комплекта.": "A post gets one photo, and the set rotates in a loop with no repeats: the photo waiting the longest becomes the cover, so identical pictures never follow one another. You can pick many files at once — all of them are saved. There is no album: it dumped every uploaded photo into a single post. Empty — pictures from the built-in set are used.",
      "Свои картинки для вечернего выпуска: тот же круг без повторов. Если пусто — дайджест возьмёт фото постов. Можно выбрать сразу много файлов.": "Your own pictures for the evening issue: the same loop with no repeats. If empty, the digest takes the post photos. You can pick many files at once.",
