      "Стереть всю статистику посещений?": "清除全部访问统计？",
      "Исчезнут переходы и уникальные посетители, график за две недели, страны, источники переходов, время на сайте и список «кто онлайн». Пользователи, подписки и рассылки останутся. Вернуть статистику нельзя.": "浏览量、独立访客、两周图表、国家、流量来源、停留时间和“当前在线”列表都会消失。用户、订阅和群发不受影响。统计无法恢复。",
