      "Исчезнут переходы и уникальные посетители, график за две недели, страны, источники переходов, время на сайте и список «кто онлайн».": "浏览量、独立访客、两周图表、国家、流量来源、停留时间和“当前在线”列表都会消失。",
      "Пользователи, подписки и рассылки останутся.": "用户、订阅和群发不受影响。",
      "Вернуть статистику нельзя.": "统计无法恢复。",
      "Отмена": "取消",
      "В пост уходит одно фото, и набор листается по кругу без повторов: обложкой идёт то фото, которое дольше всех не выходило, поэтому одинаковые картинки подряд не повторяются.": "一条帖子只配一张图，图集按循环轮换且不重复：等待最久的图片当封面，所以相同图片不会连续出现。",
