      "jpg, png, webp — до 12 МБ каждое, можно выбрать пачку": "jpg、png、webp —— 每张最大 12 MB，可选择一批",
      "В пост уходит одно фото, и набор листается по кругу без повторов: обложкой идёт то фото, которое дольше всех не выходило, поэтому одинаковые картинки подряд не повторяются. Файлов можно выбрать сразу много — сохранятся все. Альбома нет: он валил все загруженные фото в один пост. Пусто — берутся картинки из комплекта.": "一条帖子只配一张图，图集按循环轮换且不重复：等待最久的图片当封面，所以相同图片不会连续出现。可以一次选择很多文件 —— 全部都会保存。不使用相册：相册会把所有上传的图片塞进一条帖子。为空 — 使用内置图集。",
      "Свои картинки для вечернего выпуска: тот же круг без повторов. Если пусто — дайджест возьмёт фото постов. Можно выбрать сразу много файлов.": "为晚间发布的期号准备自己的图片：同样是不重复的循环。如果为空，摘要会使用帖子的图片。可以一次选择多个文件。",
