      "jpg, png, webp — до 12 МБ каждое, можно выбрать пачку": "jpg, png, webp — hasta 12 MB cada uno, puedes seleccionar un lote",
      "В пост уходит одно фото, и набор листается по кругу без повторов: обложкой идёт то фото, которое дольше всех не выходило, поэтому одинаковые картинки подряд не повторяются. Файлов можно выбрать сразу много — сохранятся все. Альбома нет: он валил все загруженные фото в один пост. Пусто — берутся картинки из комплекта.": "Cada post lleva una sola foto y el conjunto rota en bucle sin repeticiones: la foto que lleva más tiempo sin salir se convierte en portada, así que las imágenes iguales no salen seguidas. Puedes elegir muchos archivos a la vez: se guardan todos. No hay álbum: metía todas las fotos subidas en un solo post. Vacío: se usan las imágenes del conjunto integrado.",
